//43f100 pulse, RNG, smoke allocation, contact call order and signed lifetime.
import ghidra.app.emulator.EmulatorHelper;
import java.io.PrintWriter;
public class ZNativeWorldFireOracle extends ZNativeWorldEffectOracle{
 int eh,events;
 void event(int...vs){events++;for(int v:vs)eh=(eh^v)*16777619;}
 void execute(EmulatorHelper e,int base,int s)throws Exception{eh=0x811c9dc5;events=0;calls=0;seed=s;e.writeRegister("ESP",S);put(e,S,4,RET);e.writeRegister("ECX",O);e.writeRegister("EDX",base);e.setBreakpoint(toAddr(RET));if(!e.run(toAddr(0x43f100),null,monitor))throw new Exception(e.getLastError());while(e.readRegister("EIP").longValue()!=RET){long pc=e.readRegister("EIP").longValue(),sp=e.readRegister("ESP").longValue();if(pc==0x460910)e.writeRegister("EAX",(seed*7919^(calls++)*2027^0x7731a5c9)&0xffffffffL);else if(pc==0x43f080){long ptr=read(e,sp+4,4);event(0,(short)e.readRegister("ECX").intValue(),(short)e.readRegister("EDX").intValue(),(int)read(e,ptr,1));if((s&1)!=0){int n=(int)read(e,ptr,1)/2;put(e,ptr,1,n==0?1:n);}}else if(pc==0x41f580)event(1,(short)e.readRegister("ECX").intValue(),(short)e.readRegister("EDX").intValue(),(int)read(e,sp+4,4)&255,(int)read(e,0x4d0277,1),(int)read(e,0x4a6f4f,1));else throw new Exception("Unexpected "+Long.toHexString(pc));long r=read(e,sp,4);e.writeRegister("ESP",sp+4);if(!e.run(toAddr(r),null,monitor))throw new Exception(e.getLastError());}}
 public void run()throws Exception{try(PrintWriter out=new PrintWriter(getScriptArgs()[0])){EmulatorHelper e=new EmulatorHelper(currentProgram);try{for(long a:new long[]{0x460910,0x43f080,0x41f580})e.setBreakpoint(toAddr(a));int[]bases={557,5848,5854,5836,469,5840,5844,0};for(int s=0;s<4096;s++){byte[]o=new byte[44],pool=new byte[120];for(int i=0;i<44;i++)o[i]=(byte)(s+i*17);for(int i=0;i<120;i++)pool[i]=(byte)(s+i*19);e.writeMemory(toAddr(O),o);e.writeMemory(toAddr(0x5a112e),pool);int free=(s>>2)%21;for(int i=0;i<20;i++)put(e,0x5a112e+i*6,2,i<free?100+i:-1);put(e,O,2,346);put(e,O+2,2,420);put(e,O+18,1,s);put(e,O+34,1,s*17);put(e,O+39,1,s&3);put(e,0x4a69f6,1,s*13);put(e,0x4a6f4f,1,0);put(e,0x4a6e73,1,0);execute(e,bases[s/256%8],s);out.println("{\"scenario\":"+s+",\"objectHash\":"+hash(e.readMemory(toAddr(O),44))+",\"smokeHash\":"+hash(e.readMemory(toAddr(0x5a112e),120))+",\"calls\":"+calls+",\"events\":"+events+",\"eventHash\":"+(eh&0xffffffffL)+"}");}}finally{e.dispose();}}}
}
